<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class DatabaseSeeder extends Seeder { public function run(): void { DB::table('countries')->upsert([['code'=>'MM','name'=>'Myanmar','is_active'=>true,'created_at'=>now(),'updated_at'=>now()],['code'=>'SG','name'=>'Singapore','is_active'=>true,'created_at'=>now(),'updated_at'=>now()],['code'=>'US','name'=>'United States','is_active'=>true,'created_at'=>now(),'updated_at'=>now()]],['code'],['name','is_active','updated_at']); foreach(['MM','SG','US'] as $code) DB::table('country_capabilities')->updateOrInsert(['country_code'=>$code],['registration_enabled'=>true,'kyc_enabled'=>false,'wallet_enabled'=>false,'deposits_enabled'=>false,'withdrawals_enabled'=>false,'transfers_enabled'=>false,'fx_enabled'=>false,'created_at'=>now(),'updated_at'=>now()]); foreach(['platform_super_admin','compliance_admin','support_agent','merchant_owner','merchant_manager','customer'] as $role) DB::table('roles')->updateOrInsert(['name'=>$role],['id'=>(string) Str::uuid(),'guard_name'=>'web','created_at'=>now(),'updated_at'=>now()]); } }
